WITH o AS (INSERT INTO opportunities (is_synthetic, source_id, official_identifier, official_title, title_lang, summary_plain, summary_origin, opportunity_type, publishing_authority, canonical_url, application_url, opens_at, closes_at, deadline_state, deadline_kind, deadline_is_date_only, deadline_timezone, deadline_original_text, last_retrieved_at, last_verified_at, status, status_confidence, status_evidence, status_reason, review_status, publication_basis, external_key, record_kind, stale_after_days, uncertainties, requirement_set_completeness, has_conflict, funding_intensity_pct, official_details) VALUES (false, (SELECT id FROM sources WHERE slug = 'opske'), '76_Δ.1.2', 'Ενίσχυση συνεργασίας μεταξύ επιχειρήσεων και ερευνητικών φορέων στους τομείς προτεραιότητας της Περιφέρειας Νοτίου Αιγαίου', 'el', 'Έργα έρευνας και ανάπτυξης ΜμΕ στο Νότιο Αιγαίο, μόνες ή σε συνεργασία με ερευνητικούς φορείς. Ένταση 35%–80% ανάλογα με την κατηγορία έρευνας και τη συνεργασία. €50.000–€250.000 για μία επιχείρηση, €80.000–€400.000 για δύο ή περισσότερες. ΓΑΚ (άρθρα 25, 28).', 'admin', 'grant', 'Περιφέρεια Νοτίου Αιγαίου — Πρόγραμμα «Νότιο Αιγαίο 2021-2027» (ΕΦΕΠΑΕ)', 'https://opske.gr/el/call/enishysi-synergasias-metaxy-epiheiriseon-kai-ereynitikon-foreon-stoys-tomeis-proteraiotitas', 'https://app.opske.gr/', '2026-10-09T10:00:00Z', '2026-12-11T13:00:00Z', 'known', 'official', false, 'Europe/Athens', '11/12/2026 15:00 (σελίδες ΟΠΣΚΕ και ΕΦΕΠΑΕ)', '2026-10-20T18:30:00+03:00', '2026-10-20T18:30:00+03:00', 'open', 'high', '{"checked_at": "2026-10-20T18:30:00+03:00", "method": "manual review of the official call document and its latest amendment", "governing_document": "Πρόσκληση Α.Π. 1939/31-07-2026 (κωδ. 76_Δ.1.2, ΟΠΣ 24767)· 1η τροποποίηση 19/10/2026 στη σελίδα ΕΦΕΠΑΕ", "sources": ["https://opske.gr/el/call/enishysi-synergasias-metaxy-epiheiriseon-kai-ereynitikon-foreon-stoys-tomeis-proteraiotitas", "https://opske.gr/sites/default/files/calls/2026-08/a_1939_31.07.2026_prosklisi_syne